        <view class="info-value">{{ doctorInfo.specialty }}</view>
      </view>
      <view class="info-item">
        <view class="info-label">联系电话</view>
        <view class="info-value">{{ doctorInfo.phone }}</view>
      </view>
      <view class="info-item">
        <view class="info-label">邮箱</view>
        <view class="info-value">{{ doctorInfo.email }}</view>
      </view>
    </view>
    
    <view class="stats-card">
