import { uniShowToast, uniNavigateTo } from '@/utils/uniHelper';

// 模拟医生信息
const doctorInfo = ref({
  id: 'D20230001',
  name: '张医生',
  title: '主治医师',
  department: '内科',
  specialty: '呼吸系统疾病、常见感冒、发热',
  phone: '138****1234',
  email: 'zhang.doctor@hospital.edu.cn'
});

// 模拟统计数据
const stats = ref({
  totalPatients: 128,
  completedVisits: 120,
  scheduleChanges: 2
});

const logout = async () => {
  await uniShowToast({ title: '退出成功' });
  setTimeout(() => {
    uniNavigateTo({ url: '/pages/login/login' });
  }, 1500);
};

const goBack = () => {
  uniNavigateTo({ url: '/pages/doctor/schedule/schedule' });
};

onMounted(() => {
  // 可以在这里加载医生信息和统计数据
});
